import numpy as np
import time
from scipy.optimize import minimize_scalar


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    # knot values with zero endpoints
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    # ||f*f||_2^2 = sum_j (L_j^2 + L_j L_{j+1} + L_{j+1}^2)/3
    a = Lp[:-1]
    b = Lp[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    linf = Lp.max()
    if linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def _discretize(fn, N):
    # N steps on x in [-1,1]; sample at step midpoints
    x = (np.arange(N) + 0.5) * (2.0 / N) - 1.0
    h = fn(x)
    h = np.maximum(h, 0.0)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 2001

    families = []

    def tri(x):
        return 1.0 - np.abs(x)
    families.append(("triangle", tri, None))

    def semicircle(x):
        return np.sqrt(np.maximum(1.0 - x * x, 0.0))
    families.append(("sqrt(1-x^2)", semicircle, None))

    def cospi(x):
        return np.cos(np.pi * x / 2.0)
    families.append(("cos(pi x/2)", cospi, None))

    def raised(x):
        return (1.0 + np.cos(np.pi * x)) / 2.0
    families.append(("(1+cos(pi x))/2", raised, None))

    for p in [0.5, 1.0, 1.5, 2.0, 3.0]:
        def mk(pp):
            return lambda x: np.maximum(1.0 - x * x, 0.0) ** pp
        families.append(("(1-x^2)^%g" % p, mk(p), ("p", p)))

    for a in [1.0, 2.0, 4.0]:
        def mk2(aa):
            return lambda x: np.exp(-aa * x * x)
        families.append(("exp(-%g x^2)" % a, mk2(a), ("a", a)))

    best_score = -1.0
    best_h = None
    best_name = None

    for name, fn, param in families:
        if time.process_time() - t0 > budget_seconds * 0.5:
            break
        h = _discretize(fn, N)
        sc = _R(h)
        if sc > best_score:
            best_score = sc
            best_h = h
            best_name = name

    # Refine the best parametric family
    refined = None
    if best_name is not None and best_name.startswith("(1-x^2)^"):
        # recover p from name
        p0 = float(best_name.split("^")[1])
        def obj(p):
            if p <= 0:
                return 1e9
            h = _discretize(lambda x: np.maximum(1.0 - x * x, 0.0) ** p, N)
            return -_R(h)
        res = minimize_scalar(obj, bounds=(0.05, 6.0), method="bounded",
                              options={"xatol": 1e-3})
        if res.fun < -best_score:
            p = res.x
            h = _discretize(lambda x: np.maximum(1.0 - x * x, 0.0) ** p, N)
            refined = (h, -res.fun, "(1-x^2)^%g" % p)
    elif best_name is not None and best_name.startswith("exp("):
        a0 = float(best_name.split("-")[1].split(" ")[0])
        def obj(a):
            if a <= 0:
                return 1e9
            h = _discretize(lambda x: np.exp(-a * x * x), N)
            return -_R(h)
        res = minimize_scalar(obj, bounds=(0.05, 20.0), method="bounded",
                              options={"xatol": 1e-3})
        if res.fun < -best_score:
            a = res.x
            h = _discretize(lambda x: np.exp(-a * x * x), N)
            refined = (h, -res.fun, "exp(-%g x^2)" % a)

    if refined is not None and refined[1] > best_score:
        best_h, best_score, best_name = refined

    # Also compare against start
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0:
            ss = _R(hs)
            if ss > best_score:
                best_h = hs
                best_score = ss
                best_name = "start"

    if best_h is None:
        best_h = np.ones(50)

    print("best family: %s  R=%.6f  N=%d  CPU %.2fs" %
          (best_name, best_score, best_h.size, time.process_time() - t0))
    return best_h

import time
import numpy as np
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    den = (np.sum(h)**2) * np.max(L)
    return num / den if den > 0 else 0.0


def _negR(h):
    if np.any(h < 0):
        return 1e10
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    s = np.sum(h)
    if s <= 0:
        return 1e10
    M = np.max(L)
    if M <= 0:
        return 1e10
    return -num / (s * s * M)


def _smooth_obj(h, p):
    if np.any(h < 0):
        return 1e10
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    s = np.sum(h)
    if s <= 0:
        return 1e10
    M = np.sum(L**p)**(1.0 / p)
    if M <= 0:
        return 1e10
    return -num / (s * s * M)


def _pad_to(h, N):
    h = np.asarray(h, dtype=float)
    if len(h) >= N:
        return h[:N].copy()
    pad = N - len(h)
    left = pad // 2
    right = pad - left
    return np.concatenate((np.zeros(left), h, np.zeros(right)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds * 0.82

    candidates = []
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if np.any(s > 0):
            candidates.append(s)

    # baseline triangle if nothing
    if not candidates:
        N = 101
        i = np.arange(N)
        candidates.append(1.0 + np.minimum(i, N - 1 - i).astype(float))

    best_h = candidates[0].copy()
    best_R = _R(best_h)

    for c in candidates:
        r = _R(c)
        if r > best_R:
            best_R = r
            best_h = c.copy()

    # Try resizing the best solution to nearby N values, then optimize.
    base = best_h.copy()
    Ns = sorted(set([len(base)] + [int(len(base) * f) for f in
                  (0.75, 0.9, 1.1, 1.25, 1.5, 2.0) if 20 <= int(len(base) * f) <= 50000]))

    def run_opt(h0, maxiter, ftol):
        bounds = [(0.0, None)] * len(h0)
        cur = h0.copy()
        curR = _R(cur)
        for p in (20.0, 40.0, 80.0):
            if time.process_time() - t0 > deadline:
                break
            try:
                res = minimize(_smooth_obj, cur, args=(p,), method='L-BFGS-B',
                               bounds=bounds,
                               options={'maxiter': maxiter, 'maxfun': 400000,
                                        'ftol': ftol, 'gtol': 1e-13})
                cand = np.maximum(res.x, 0.0)
                r = _R(cand)
                if r > curR:
                    curR = r
                    cur = cand
            except Exception:
                break
        return cur, curR

    cur, curR = run_opt(base, 3000, 1e-16)
    if curR > best_R:
        best_R, best_h = curR, cur

    # Try other N's
    for N in Ns:
        if N == len(best_h):
            continue
        if time.process_time() - t0 > deadline:
            break
        h0 = _pad_to(best_h, N)
        # rescale height by 1/N to keep magnitudes reasonable
        h0 = h0 * (len(best_h) / N)
        cur, curR = run_opt(h0, 1500, 1e-14)
        if curR > best_R:
            best_R, best_h = curR, cur

    # Local polish: add small random perturbations and refine
    rng = np.random.default_rng(12345)
    while time.process_time() - t0 < deadline:
        if len(best_h) == 0:
            break
        scale = 0.03 * (np.mean(best_h) + 1e-12)
        h0 = np.maximum(best_h + scale * rng.standard_normal(len(best_h)), 0.0)
        cur, curR = run_opt(h0, 800, 1e-14)
        if curR > best_R:
            best_R, best_h = curR, cur

    # final exact polish with a tight smooth max
    if time.process_time() - t0 < budget_seconds * 0.95:
        try:
            bounds = [(0.0, None)] * len(best_h)
            res = minimize(_smooth_obj, best_h, args=(200.0,), method='L-BFGS-B',
                           bounds=bounds,
                           options={'maxiter': 2000, 'maxfun': 200000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            cand = np.maximum(res.x, 0.0)
            r = _R(cand)
            if r > best_R:
                best_R, best_h = r, cand
        except Exception:
            pass

    print("final exact R = %.9f" % best_R)
    return best_h
